import{_ as e,c as t,o as a,N as o}from"./chunks/framework.L4jCtPdF.js";const m=JSON.parse('{"title":"FAQ / Troubleshooting","description":"","frontmatter":{"title":"FAQ / Troubleshooting","order":10,"outline":[0,4]},"headers":[],"relativePath":"products/ultra-wallet-sdk/faq-and-troubleshooting.md","filePath":"products/ultra-wallet-sdk/faq-and-troubleshooting.md","lastUpdated":null}'),n={name:"products/ultra-wallet-sdk/faq-and-troubleshooting.md"},s=o('<h1 id="faq-troubleshooting" tabindex="-1">FAQ / Troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ / Troubleshooting&quot;">​</a></h1><h2 id="nothing-happens-when-i-call-connect" tabindex="-1">Nothing happens when I call <code>connect()</code> <a class="header-anchor" href="#nothing-happens-when-i-call-connect" aria-label="Permalink to &quot;Nothing happens when I call `connect()`&quot;">​</a></h2><p>With the Web Wallet, this is almost always a <strong>blocked popup</strong>. The promise rejects with <code>4301</code>.</p><ul><li>Call the method directly from a click or tap handler. See <a href="./getting-started.html#call-wallet-methods-from-a-user-gesture">User gestures</a>.</li><li>Check that the user has not blocked popups for your site.</li><li>If the popup opens but stays blank, and the call rejects with <code>4300</code> after 10 seconds, the Web Wallet could not load. Check the <code>environment</code> value and the network connection.</li></ul><h2 id="connect-throws-wallet-environment-mismatch" tabindex="-1"><code>connect()</code> throws &quot;Wallet environment mismatch&quot; <a class="header-anchor" href="#connect-throws-wallet-environment-mismatch" aria-label="Permalink to &quot;`connect()` throws &quot;Wallet environment mismatch&quot;&quot;">​</a></h2><p>The extension is on a different network from the <code>environment</code> you configured. Ask the user to switch networks in the extension, or build your app for the network they use. See <a href="./getting-started.html#options">Options</a>.</p><p>If the message says <code>received &quot;null&quot;</code>, the extension could not reach its network node. Ask the user to check their connection or the network&#39;s node in the extension settings.</p><h2 id="i-have-the-extension-installed-but-the-sdk-opens-the-web-wallet" tabindex="-1">I have the extension installed, but the SDK opens the Web Wallet <a class="header-anchor" href="#i-have-the-extension-installed-but-the-sdk-opens-the-web-wallet" aria-label="Permalink to &quot;I have the extension installed, but the SDK opens the Web Wallet&quot;">​</a></h2><ul><li><strong>Local development on <code>http://localhost</code>:</strong> the Chrome Web Store build of the extension runs only on HTTPS pages. Serve your app over HTTPS. See <a href="./getting-started.html#choosing-a-provider">Choosing a provider</a>.</li><li><strong>Your app runs inside an iframe.</strong> The extension injects <code>window.ultra</code> into top-level pages only.</li><li>Check that the extension is enabled for the site in the browser&#39;s extension settings.</li></ul><h2 id="can-any-ultra-account-use-the-web-wallet" tabindex="-1">Can any Ultra account use the Web Wallet? <a class="header-anchor" href="#can-any-ultra-account-use-the-web-wallet" aria-label="Permalink to &quot;Can any Ultra account use the Web Wallet?&quot;">​</a></h2><p>The Web Wallet supports <strong>Easy Blockchain Accounts</strong> (EBA) only, meaning accounts created through Ultra sign-up. Users with self-managed keys should use the Browser Extension.</p><h2 id="getaccounts-switchnetwork-events-don-t-work" tabindex="-1"><code>getAccounts()</code> / <code>switchNetwork()</code> / events don&#39;t work <a class="header-anchor" href="#getaccounts-switchnetwork-events-don-t-work" aria-label="Permalink to &quot;`getAccounts()` / `switchNetwork()` / events don&#39;t work&quot;">​</a></h2><p>These are extension-only features. With the Web Wallet provider, they reject, throw or do nothing. See the <a href="./#provider-support">provider support table</a>.</p><h2 id="getaccounts-returns-strings-not-objects" tabindex="-1"><code>getAccounts()</code> returns strings, not objects <a class="header-anchor" href="#getaccounts-returns-strings-not-objects" aria-label="Permalink to &quot;`getAccounts()` returns strings, not objects&quot;">​</a></h2><p>Extension 2.2.13 and earlier return bare account names. See <a href="./accounts-and-networks.html#getaccounts">getAccounts()</a>.</p><h2 id="connect-says-it-succeeded-but-accounts-is-empty-or-missing" tabindex="-1"><code>connect()</code> says it succeeded, but <code>accounts</code> is empty or missing <a class="header-anchor" href="#connect-says-it-succeeded-but-accounts-is-empty-or-missing" aria-label="Permalink to &quot;`connect()` says it succeeded, but `accounts` is empty or missing&quot;">​</a></h2><ul><li>With the <strong>Web Wallet</strong>, only <code>blockchainid</code> and <code>publicKey</code> are returned.</li><li>With the <strong>extension</strong>, accounts are resolved on the wallet&#39;s current network. A user whose accounts exist only on mainnet has no accounts while the wallet is on testnet.</li></ul><h2 id="my-transaction-fails-with-an-authorization-error" tabindex="-1">My transaction fails with an authorization error <a class="header-anchor" href="#my-transaction-fails-with-an-authorization-error" aria-label="Permalink to &quot;My transaction fails with an authorization error&quot;">​</a></h2><ul><li>The transaction must be authorized by an account and permission the wallet holds a key for. Check with <a href="./accounts-and-networks.html#getavailableauthorizations"><code>getAvailableAuthorizations()</code></a>.</li><li>Omit the authorization to use the connected account with <code>active</code>.</li><li>With Web Wallet releases before September 2026, also pass custom authorizations in the legacy <code>authorizations</code> field. See <a href="./signing.html#authorizations">Authorizations</a>.</li></ul><h2 id="signmessage-fails-with-missing-or-invalid-parameters" tabindex="-1"><code>signMessage()</code> fails with &quot;Missing or invalid parameters&quot; <a class="header-anchor" href="#signmessage-fails-with-missing-or-invalid-parameters" aria-label="Permalink to &quot;`signMessage()` fails with &quot;Missing or invalid parameters&quot;&quot;">​</a></h2><p>The message must start with <code>message:</code>, <code>0x</code> or <code>UOSx</code>.</p><h2 id="can-i-use-the-sdk-in-a-mobile-browser" tabindex="-1">Can I use the SDK in a mobile browser? <a class="header-anchor" href="#can-i-use-the-sdk-in-a-mobile-browser" aria-label="Permalink to &quot;Can I use the SDK in a mobile browser?&quot;">​</a></h2><p>Mobile browsers do not support the Browser Extension, so the SDK uses the Web Wallet. Popup handling differs between mobile browsers, so test your flow on your target devices, and call wallet methods directly from taps.</p><h2 id="can-i-switch-between-mainnet-and-testnet-at-runtime" tabindex="-1">Can I switch between mainnet and testnet at runtime? <a class="header-anchor" href="#can-i-switch-between-mainnet-and-testnet-at-runtime" aria-label="Permalink to &quot;Can I switch between mainnet and testnet at runtime?&quot;">​</a></h2><ul><li><strong>Extension:</strong> yes, with <a href="./accounts-and-networks.html#switchnetwork"><code>switchNetwork()</code></a> once connected.</li><li><strong>Web Wallet:</strong> no. The Web Wallet serves mainnet only; with <code>environment: &#39;testnet&#39;</code>, SDK 0.6.1+ rejects Web Wallet calls with <code>4302</code>. Testnet users need the extension.</li></ul><h2 id="where-are-the-keys-stored-can-the-dapp-access-them" tabindex="-1">Where are the keys stored? Can the dApp access them? <a class="header-anchor" href="#where-are-the-keys-stored-can-the-dapp-access-them" aria-label="Permalink to &quot;Where are the keys stored? Can the dApp access them?&quot;">​</a></h2><p>No, a dApp can never read private keys. It receives only public keys, signatures and transaction results.</p><ul><li><strong>Browser Extension:</strong> keys are kept in the extension&#39;s encrypted vault, unlocked with the user&#39;s password.</li><li><strong>Web Wallet:</strong> keys are generated in the browser and stored in an encrypted vault. The encryption key is assembled from a device-local part and a part from Ultra&#39;s device service, so Ultra never holds the complete key. See <a href="./../ultra-web-wallet/security.html">Ultra Web Wallet → Security</a>.</li></ul><h2 id="can-i-call-window-ultra-directly-instead-of-using-the-sdk" tabindex="-1">Can I call <code>window.ultra</code> directly instead of using the SDK? <a class="header-anchor" href="#can-i-call-window-ultra-directly-instead-of-using-the-sdk" aria-label="Permalink to &quot;Can I call `window.ultra` directly instead of using the SDK?&quot;">​</a></h2><p>Yes. The extension&#39;s <code>window.ultra</code> API is documented under <a href="./../ultra-wallet/">Ultra Wallet</a>. The SDK is recommended: it also supports Web Wallet users, checks the network, and handles event registration for you.</p>',30),r=[s];function i(l,c,h,d,u,p){return a(),t("div",null,r)}const b=e(n,[["render",i]]);export{m as __pageData,b as default};
